def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    priority = {"pass": 0, "skip": 1, "fail": 2}

    def update(name: str, status: str) -> None:
        if not name or status not in priority:
            return
        prev = results.get(name)
        if prev is None or priority[status] >= priority[prev]:
            results[name] = status

    go_line = re.compile(r"^\s*---\s+(PASS|FAIL|SKIP):\s+([^\s]+)")
    simple_line = re.compile(r"^(PASS|FAIL|SKIP):\s+([^\s]+)")
    pytest_line = re.compile(r"^(?P<name>\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b")
    unittest_line = re.compile(r"^(?P<name>\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", re.IGNORECASE)
    jest_line = re.compile(r"^\s*([✓✕○])\s+(.+?)\s*$")

    def parse_status_from_line(line: str) -> None:
        m = go_line.match(line)
        if m:
            update(m.group(2), m.group(1).lower())
            return
        m = simple_line.match(line)
        if m:
            update(m.group(2), m.group(1).lower())
            return
        m = pytest_line.match(line)
        if m:
            status = m.group(2).lower()
            if status in ("failed", "error"):
                status = "fail"
            elif status == "skipped":
                status = "skip"
            elif status == "passed":
                status = "pass"
            update(m.group("name"), status)
            return
        m = unittest_line.match(line)
        if m:
            status = m.group(2).lower()
            if status in ("fail", "error"):
                status = "fail"
            elif status == "skipped":
                status = "skip"
            elif status == "ok":
                status = "pass"
            update(m.group("name"), status)
            return
        m = jest_line.match(line)
        if m:
            symbol = m.group(1)
            name = m.group(2).strip()
            if symbol == "✓":
                update(name, "pass")
            elif symbol == "✕":
                update(name, "fail")
            elif symbol == "○":
                update(name, "skip")

    for raw_line in log.splitlines():
        if not raw_line.strip():
            continue

        stripped = raw_line.strip()
        parsed_json = False
        if stripped.startswith("{") and stripped.endswith("}"):
            try:
                event = json.loads(stripped)
                parsed_json = True
            except json.JSONDecodeError:
                parsed_json = False

        if parsed_json:
            action = event.get("Action")
            test = event.get("Test")
            if action in ("pass", "fail", "skip") and test:
                update(test, "fail" if action == "fail" else action)
            output = event.get("Output")
            if output:
                for out_line in output.splitlines():
                    parse_status_from_line(out_line)
        else:
            parse_status_from_line(raw_line)

    return results
